/**
 * How many times a query is attempted in total, the first try included.
 */
export const MAX_QUERY_ATTEMPTS = 3

/**
 * Decides whether a failed query is worth attempting again.
 *
 * Only a `5xx` is: it says the server could not answer, so the same question
 * asked again may get one. Every other outcome is an answer already.
 *
 * @param failureCount how many attempts have already failed
 * @param error whatever the query function threw
 */
export function shouldRetryQuery(failureCount: number, error: unknown): boolean {
  const status = httpStatusOf(error)
  return failureCount < MAX_QUERY_ATTEMPTS - 1 && status !== undefined && status >= 500
}

function httpStatusOf(error: unknown): number | undefined {
  if (typeof error !== 'object' || error === null) return undefined
  const status = (error as { status?: unknown }).status
  return typeof status === 'number' ? status : undefined
}

import react from '@vitejs/plugin-react'
import { tanstackRouter } from '@tanstack/router-plugin/vite'
import { defineConfig } from 'vite'

const backend = process.env.BACKEND_ORIGIN ?? 'http://localhost:8080'

/**
 * The Spring application runs as its own process, and owns `/api` and
 * `/internal`. Proxying them keeps the browser on one origin in development.
 */
const toBackend = {
  target: backend,
  changeOrigin: true,
  // The proxy forwards the browser's `Accept-Encoding` upstream, so a backend
  // that compresses would compress the event stream too — and a gzip encoder
  // holds a two-line event until it has enough bytes, which means every event
  // arrives in one clump when the connection closes, in development only.
  // Asking this hop for `identity` puts that failure out of reach.
  headers: { 'Accept-Encoding': 'identity' },
}

export default defineConfig({
  plugins: [
    tanstackRouter({ target: 'react', autoCodeSplitting: true }),
    react(),
  ],
  server: {
    port: 5173,
    strictPort: true,
    proxy: {
      '/api': toBackend,
      '/internal': toBackend,
    },
  },
})

import { createFileRoute } from '@tanstack/react-router'

export const Route = createFileRoute('/accounts')({ component: AccountsScreen })

function AccountsScreen() {
  return (
    <>
      <h1 className="h3">Accounts</h1>
      <p className="text-body-secondary">Every account, its balance and what it can spend.</p>
    </>
  )
}

import { createFileRoute } from '@tanstack/react-router'

export const Route = createFileRoute('/transfers/$transferId')({ component: TransferScreen })

function TransferScreen() {
  const { transferId } = Route.useParams()

  return (
    <>
      <h1 className="h3">Transfer {transferId}</h1>
      <p className="text-body-secondary">
        The live one — the only screen that holds an event-stream connection.
      </p>
    </>
  )
}

import { createFileRoute } from '@tanstack/react-router'

export const Route = createFileRoute('/transfers/')({ component: TransactionsScreen })

function TransactionsScreen() {
  return (
    <>
      <h1 className="h3">Transactions</h1>
      <p className="text-body-secondary">Every transfer, in every state.</p>
    </>
  )
}

import { createFileRoute } from '@tanstack/react-router'

export const Route = createFileRoute('/transfers/new')({ component: NewTransferScreen })

function NewTransferScreen() {
  return (
    <>
      <h1 className="h3">New transfer</h1>
      <p className="text-body-secondary">
        Submitting navigates to the transfer, so pending state lives in the URL.
      </p>
    </>
  )
}

